use std::{sync::Arc, time::Instant};
use volna_trace::{session::{LocalSession, Session}, remote::{objects::{TrackPayload, Metadata}, session::RemoteSession, tracks::{TrackDecoder, TrackStep}, memory::MemoryBudget, transport::DATA_BYTES}};
fn main() {
    let args:Vec<_>=std::env::args().collect();
    let local=LocalSession::open(std::path::Path::new(&args[1])).unwrap();
    let selected=local.tracks().iter().find(|t|t.path.join(".").contains("warp_slot[0].Instruction")).unwrap();
    let loaded=local.load_track(selected.id).unwrap();
    let start=Instant::now();
    let payload=TrackPayload::from_loaded(&loaded);
    let len=bincode::serialized_size(&payload).unwrap();
    let mut bytes=Vec::with_capacity(len as usize);
    bincode::serialize_into(&mut bytes,&payload).unwrap();
    assert_eq!(bytes.len() as u64,len);
    let encode=start.elapsed().as_secs_f64();
    let session=Arc::new(RemoteSession::new(11,Metadata::from_session(&local)).unwrap());
    let budget=MemoryBudget::new(2<<30);
    let start=Instant::now();
    let mut decoder=TrackDecoder::new(len,2<<30,&budget,session).unwrap();
    let mut chunks=bytes.chunks(DATA_BYTES);
    let decoded=loop {
        match decoder.step().unwrap() {
            TrackStep::NeedInput=>decoder.feed(chunks.next().unwrap().to_vec()).unwrap(),
            TrackStep::Yield=>(),
            TrackStep::Decoded(track)=>break track,
        }
    };
    let decode=start.elapsed().as_secs_f64();
    assert!(chunks.next().is_none());
    let rows=decoded.generators.iter().map(|g|g.transactions().len()).sum::<usize>();
    let checksum=decoded.generators.iter().flat_map(|g|g.transactions()).fold(0u64,|sum,t|sum.wrapping_add(t.id.0).wrapping_add(t.begin).wrapping_add(t.end));
    println!("{{\"encode\":{encode},\"decode\":{decode},\"wire_bytes\":{len},\"admitted_bytes\":{},\"rows\":{rows},\"checksum\":{checksum}}}",budget.used());
    drop(decoded);drop(decoder);assert_eq!(budget.used(),0);
}

