use volna_trace::remote::{hierarchy::Header, memory::MemoryBudget, metadata::{MetadataDecoder, MetadataStep}};
use volna_trace::session::LocalSession;
use vtr::{Attribute, Recorder, SourceOptions, Value, Writer};

fn recording(depth: usize, width: usize) -> LocalSession {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("graph-{depth}-{width}.vtr"));
    let mut writer = Writer::create(&path).unwrap();
    let key = writer.intern("description").unwrap();
    let mut id = writer.intern_value(Value::Text("description".repeat(4))).unwrap();
    for _ in 0..depth {
        id = writer.intern_value(Value::List(vec![Value::Ref(id); width])).unwrap();
    }
    let mut options = SourceOptions::new("instructions", None);
    options.attributes = vec![Attribute { key, value: Value::Ref(id) }];
    writer.transactions::<()>(options, "INSTRUCTION").unwrap();
    writer.close().unwrap();
    println!("depth={depth} width={width} VTR_bytes={}", std::fs::metadata(&path).unwrap().len());
    LocalSession::open(&path).unwrap()
}

fn main() {
    for depth in [0, 63, 64, 80] {
        let session = recording(depth, 1);
        let header = Header::from_session(&session).unwrap();
        let bytes = bincode::serialize(&header).unwrap();
        let budget = MemoryBudget::new(1 << 20);
        let mut decoder = MetadataDecoder::new(bytes.len() as u64, 1 << 20, &budget).unwrap();
        decoder.feed(bytes.clone()).unwrap();
        loop {
            match decoder.step() {
                Ok(MetadataStep::Decoded(_)) => { println!("remote_bytes={} decoded=ok", bytes.len()); break; }
                Ok(MetadataStep::Yield) => (),
                Ok(MetadataStep::NeedInput) => panic!("unexpected end"),
                Err(error) => { println!("remote_bytes={} decoded=ERROR {error}", bytes.len()); break; }
            }
        }
    }
    for depth in [10, 16] {
        let session = recording(depth, 2);
        let header = Header::from_session(&session).unwrap();
        println!("remote_expanded_bytes={}", bincode::serialized_size(&header).unwrap());
    }
}
